Save this as a .html file and open it on your phone. It runs fully offline. 📱

HTML
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Content Gap Sprint Board</title>
<style>
  :root {
    --bg: #f6f2ea;
    --panel: #fffaf1;
    --panel2: #fffdf8;
    --ink: #1f2328;
    --muted: #646b75;
    --line: #ded5c6;
    --soft: #efe6d8;
    --accent: #314f3c;
    --accent2: #9b5b31;
    --danger: #8d2f2f;
    --ok: #356a48;
    --shadow: 0 10px 30px rgba(40, 32, 18, .09);
    --r: 18px;
  }

  * {
    box-sizing: border-box;
  }

  html,
  body {
    margin: 0;
    min-height: 100%;
    background: var(--bg);
    color: var(--ink);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  body {
    padding: 12px;
    overflow-x: hidden;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  button {
    touch-action: manipulation;
  }

  .app {
    width: 100%;
    max-width: 880px;
    margin: 0 auto;
  }

  header {
    background: linear-gradient(135deg, #fffaf1, #eee2cf);
    border: 1px solid var(--line);
    border-radius: 24px;
    padding: 16px;
    box-shadow: var(--shadow);
  }

  h1 {
    margin: 0 0 6px;
    font-size: clamp(1.25rem, 7vw, 2rem);
    line-height: 1.05;
    letter-spacing: -0.04em;
  }

  .lede {
    margin: 0;
    color: var(--muted);
    line-height: 1.35;
    font-size: .95rem;
  }

  .section {
    margin-top: 12px;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: var(--r);
    box-shadow: var(--shadow);
    overflow: hidden;
  }

  .section-head {
    padding: 12px 14px;
    border-bottom: 1px solid var(--line);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    background: rgba(255,255,255,.42);
  }

  .section-title {
    margin: 0;
    font-size: .95rem;
    letter-spacing: .01em;
  }

  .small {
    color: var(--muted);
    font-size: .8rem;
  }

  .form-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
    padding: 12px;
  }

  @media (min-width: 720px) {
    .form-grid.two {
      grid-template-columns: 1fr 1fr;
    }
  }

  label {
    display: grid;
    gap: 5px;
    color: var(--muted);
    font-weight: 700;
    font-size: .78rem;
    text-transform: uppercase;
    letter-spacing: .04em;
  }

  input,
  textarea,
  select {
    width: 100%;
    max-width: 100%;
    border: 1px solid var(--line);
    border-radius: 14px;
    background: var(--panel2);
    color: var(--ink);
    padding: 10px 11px;
    outline: none;
  }

  textarea {
    min-height: 84px;
    resize: vertical;
    line-height: 1.35;
  }

  input:focus,
  textarea:focus,
  select:focus {
    border-color: rgba(49, 79, 60, .65);
    box-shadow: 0 0 0 3px rgba(49, 79, 60, .12);
  }

  .toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 0 12px 12px;
  }

  .btn {
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--panel2);
    color: var(--ink);
    padding: 9px 11px;
    min-height: 40px;
    cursor: pointer;
    max-width: 100%;
  }

  .btn.primary {
    background: var(--accent);
    color: #fff;
    border-color: var(--accent);
  }

  .btn.warn {
    color: var(--danger);
  }

  .btn.tiny {
    padding: 6px 9px;
    min-height: 32px;
    font-size: .78rem;
  }

  .btn:active {
    transform: translateY(1px);
  }

  .statusbar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding: 12px;
  }

  @media (min-width: 620px) {
    .statusbar {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }
  }

  .stat {
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 10px;
    background: var(--panel2);
    min-width: 0;
  }

  .stat strong {
    display: block;
    font-size: 1.25rem;
  }

  .stat span {
    color: var(--muted);
    font-size: .78rem;
  }

  .quick-add {
    padding: 12px;
    display: grid;
    gap: 9px;
  }

  .quick-row {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
  }

  @media (min-width: 620px) {
    .quick-row {
      grid-template-columns: 1fr 170px 120px;
    }
  }

  .lane-tabs {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding: 10px 12px 2px;
    scrollbar-width: none;
  }

  .lane-tabs::-webkit-scrollbar {
    display: none;
  }

  .tab {
    white-space: nowrap;
    border: 1px solid var(--line);
    background: var(--panel2);
    border-radius: 999px;
    padding: 8px 10px;
    font-size: .8rem;
    color: var(--muted);
    cursor: pointer;
  }

  .tab.active {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
  }

  .board {
    padding: 10px 10px 12px;
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
  }

  @media (min-width: 760px) {
    .board {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  .lane {
    background: rgba(255,255,255,.48);
    border: 1px solid var(--line);
    border-radius: 18px;
    min-width: 0;
    overflow: hidden;
  }

  .lane.drop {
    outline: 3px solid rgba(49, 79, 60, .18);
  }

  .lane-head {
    padding: 10px;
    display: flex;
    align-items: start;
    justify-content: space-between;
    gap: 8px;
    border-bottom: 1px solid var(--line);
  }

  .lane-name {
    margin: 0;
    font-size: .95rem;
  }

  .lane-desc {
    margin: 3px 0 0;
    color: var(--muted);
    font-size: .78rem;
    line-height: 1.25;
  }

  .count {
    flex: 0 0 auto;
    min-width: 28px;
    text-align: center;
    border-radius: 999px;
    background: var(--soft);
    padding: 4px 7px;
    font-size: .78rem;
    color: var(--muted);
  }

  .cards {
    display: grid;
    gap: 9px;
    padding: 10px;
    min-height: 54px;
  }

  .empty {
    color: var(--muted);
    font-size: .82rem;
    border: 1px dashed var(--line);
    border-radius: 14px;
    padding: 10px;
    background: rgba(255,255,255,.45);
  }

  .card {
    background: var(--panel2);
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 10px;
    box-shadow: 0 6px 14px rgba(30, 25, 16, .05);
    min-width: 0;
  }

  .card.dragging {
    opacity: .55;
  }

  .card-top {
    display: flex;
    align-items: start;
    justify-content: space-between;
    gap: 8px;
  }

  .card-title {
    margin: 0;
    font-size: .95rem;
    line-height: 1.2;
    overflow-wrap: anywhere;
  }

  .pill {
    border-radius: 999px;
    padding: 4px 7px;
    font-size: .72rem;
    background: #eee7da;
    color: #5b5142;
    flex: 0 0 auto;
  }

  .card-detail {
    margin: 6px 0 8px;
    color: var(--muted);
    font-size: .84rem;
    line-height: 1.35;
    overflow-wrap: anywhere;
  }

  .mini-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .mini-grid select,
  .mini-grid input {
    padding: 8px;
    border-radius: 12px;
    font-size: .84rem;
  }

  @media (min-width: 520px) {
    .mini-grid {
      grid-template-columns: 1fr 1fr;
    }
  }

  .note {
    margin-top: 7px;
    min-height: 58px;
    font-size: .86rem;
  }

  .card-actions {
    margin-top: 8px;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  .include-row {
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
    color: var(--muted);
    font-size: .82rem;
  }

  .include-row input {
    width: auto;
  }

  .brief-preview {
    white-space: pre-wrap;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: .8rem;
    line-height: 1.35;
    background: #211f1a;
    color: #fff7e8;
    border-radius: 16px;
    padding: 12px;
    max-height: 280px;
    overflow: auto;
    margin: 12px;
  }

  .toast {
    position: fixed;
    left: 50%;
    bottom: 14px;
    transform: translateX(-50%) translateY(20px);
    opacity: 0;
    pointer-events: none;
    background: #1f2328;
    color: white;
    border-radius: 999px;
    padding: 10px 13px;
    font-size: .86rem;
    transition: .18s ease;
    max-width: calc(100vw - 24px);
    text-align: center;
    z-index: 50;
  }

  .toast.show {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }

  .footer-note {
    color: var(--muted);
    font-size: .78rem;
    line-height: 1.35;
    padding: 0 4px 18px;
    text-align: center;
  }

  @media (max-width: 420px) {
    body {
      padding: 8px;
    }

    header {
      padding: 14px;
      border-radius: 20px;
    }

    .section-head,
    .form-grid,
    .quick-add,
    .statusbar,
    .toolbar {
      padding-left: 10px;
      padding-right: 10px;
    }

    .btn {
      padding-left: 10px;
      padding-right: 10px;
      font-size: .86rem;
    }

    .tab {
      font-size: .76rem;
      padding: 7px 9px;
    }

    .board {
      padding-left: 8px;
      padding-right: 8px;
    }

    .card {
      padding: 9px;
    }
  }
</style>
</head>
<body>
<div class="app">
  <header>
    <h1>Content Gap Sprint Board</h1>
    <p class="lede">Paste a competitor angle, add your article idea, sort gap cards, then copy a tight brief for the article you should actually write.</p>
  </header>

  <section class="section" aria-labelledby="setupTitle">
    <div class="section-head">
      <h2 class="section-title" id="setupTitle">Article setup</h2>
      <span class="small">Offline and local</span>
    </div>

    <div class="form-grid two">
      <label>
        Topic or keyword
        <input id="topic" placeholder="Example: beginner SEO content brief">
      </label>

      <label>
        Audience
        <input id="audience" placeholder="Example: solo founders, local service businesses">
      </label>

      <label>
        Competitor article title or angle
        <textarea id="competitor" placeholder="Paste the competitor title, angle, or visible promise."></textarea>
      </label>

      <label>
        My article idea
        <textarea id="idea" placeholder="Write the article idea you want to test against the competitor."></textarea>
      </label>
    </div>

    <div class="toolbar">
      <button class="btn primary" id="seedBtn" type="button">Generate starter gaps</button>
      <button class="btn" id="copyBtn" type="button">Copy brief</button>
      <button class="btn" id="exportBtn" type="button">Export .txt</button>
      <button class="btn warn" id="resetBtn" type="button">Reset board</button>
    </div>
  </section>

  <section class="section" aria-labelledby="scoreTitle">
    <div class="section-head">
      <h2 class="section-title" id="scoreTitle">Sprint snapshot</h2>
      <span class="small" id="saveStatus">Saved</span>
    </div>
    <div class="statusbar" id="stats"></div>
  </section>

  <section class="section" aria-labelledby="addTitle">
    <div class="section-head">
      <h2 class="section-title" id="addTitle">Add a gap card</h2>
      <span class="small">Tap friendly</span>
    </div>

    <div class="quick-add">
      <div class="quick-row">
        <input id="newTitle" placeholder="Gap card title">
        <select id="newLane" aria-label="Lane">
          <option value="promise">Search promise</option>
          <option value="evidence">Evidence</option>
          <option value="faq">FAQ coverage</option>
          <option value="originality">Originality</option>
          <option value="priority">Priority</option>
          <option value="parked">Parked</option>
        </select>
        <button class="btn primary" id="addBtn" type="button">Add</button>
      </div>
      <textarea id="newDetail" placeholder="Why this gap matters, what to fix, or what proof is needed."></textarea>
    </div>
  </section>

  <section class="section" aria-labelledby="boardTitle">
    <div class="section-head">
      <h2 class="section-title" id="boardTitle">Gap board</h2>
      <span class="small">Drag or move by menu</span>
    </div>

    <div class="lane-tabs" id="tabs" aria-label="Lane filter"></div>
    <div class="board" id="board"></div>
  </section>

  <section class="section" aria-labelledby="briefTitle">
    <div class="section-head">
      <h2 class="section-title" id="briefTitle">Brief preview</h2>
      <span class="small">Updates live</span>
    </div>
    <pre class="brief-preview" id="briefPreview"></pre>
  </section>

  <p class="footer-note">Everything stays in this browser through local storage. No external libraries, fonts, APIs, or tracking.</p>
</div>

<div class="toast" id="toast" role="status" aria-live="polite"></div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "content-gap-sprint-board-v1";

  var lanes = [
    {
      id: "promise",
      name: "Search promise",
      desc: "What the result should clearly promise before the click."
    },
    {
      id: "evidence",
      name: "Evidence",
      desc: "Claims, examples, screenshots, data, or expert proof needed."
    },
    {
      id: "faq",
      name: "FAQ coverage",
      desc: "Questions the competitor misses or answers weakly."
    },
    {
      id: "originality",
      name: "Originality",
      desc: "Fresh angle, stronger framework, or lived-detail advantage."
    },
    {
      id: "priority",
      name: "Priority",
      desc: "The few gaps that most change the article."
    },
    {
      id: "parked",
      name: "Parked",
      desc: "Nice ideas, risky claims, duplicates, or skips."
    }
  ];

  var state = {
    topic: "",
    audience: "",
    competitor: "",
    idea: "",
    filter: "all",
    cards: []
  };

  var el = {
    topic: document.getElementById("topic"),
    audience: document.getElementById("audience"),
    competitor: document.getElementById("competitor"),
    idea: document.getElementById("idea"),
    seedBtn: document.getElementById("seedBtn"),
    copyBtn: document.getElementById("copyBtn"),
    exportBtn: document.getElementById("exportBtn"),
    resetBtn: document.getElementById("resetBtn"),
    stats: document.getElementById("stats"),
    saveStatus: document.getElementById("saveStatus"),
    newTitle: document.getElementById("newTitle"),
    newLane: document.getElementById("newLane"),
    newDetail: document.getElementById("newDetail"),
    addBtn: document.getElementById("addBtn"),
    tabs: document.getElementById("tabs"),
    board: document.getElementById("board"),
    briefPreview: document.getElementById("briefPreview"),
    toast: document.getElementById("toast")
  };

  function uid() {
    return "c" + Math.random().toString(16).slice(2) + Date.now().toString(16);
  }

  function cleanText(value) {
    return String(value || "").replace(/\s+/g, " ").trim();
  }

  function getLaneName(id) {
    var found = lanes.find(function (lane) {
      return lane.id === id;
    });
    return found ? found.name : "Gap";
  }

  function makeCard(lane, title, detail, impact, effort, included) {
    return {
      id: uid(),
      lane: lane,
      title: title,
      detail: detail,
      note: "",
      impact: impact || "3",
      effort: effort || "2",
      included: included !== false,
      created: Date.now()
    };
  }

  function save() {
    state.topic = el.topic.value;
    state.audience = el.audience.value;
    state.competitor = el.competitor.value;
    state.idea = el.idea.value;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    el.saveStatus.textContent = "Saved";
  }

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.cards)) {
          state = Object.assign(state, parsed);
        }
      }
    } catch (err) {
      state.cards = [];
    }

    el.topic.value = state.topic || "";
    el.audience.value = state.audience || "";
    el.competitor.value = state.competitor || "";
    el.idea.value = state.idea || "";
  }

  function debounce(fn, delay) {
    var timer;
    return function () {
      clearTimeout(timer);
      timer = setTimeout(fn, delay);
    };
  }

  function showToast(message) {
    el.toast.textContent = message;
    el.toast.classList.add("show");
    clearTimeout(showToast.timer);
    showToast.timer = setTimeout(function () {
      el.toast.classList.remove("show");
    }, 1500);
  }

  function starterCards() {
    var topic = cleanText(el.topic.value) || "this topic";
    var audience = cleanText(el.audience.value) || "the target reader";
    var comp = cleanText(el.competitor.value) || "the competitor article";
    var idea = cleanText(el.idea.value) || "your article idea";

    return [
      makeCard(
        "promise",
        "Make the search-result promise more concrete",
        "Compare the competitor promise with your idea. Replace vague benefit language with a specific outcome for " + audience + ". Competitor angle: " + comp + ".",
        "5",
        "2",
        true
      ),
      makeCard(
        "promise",
        "Match intent before adding cleverness",
        "Check whether the searcher wants a guide, checklist, comparison, examples, template, or warning. Shape the title and intro around that first.",
        "4",
        "2",
        true
      ),
      makeCard(
        "promise",
        "Add a stronger reason to click your result",
        "Give the reader a visible advantage over the competitor, such as faster triage, clearer examples, a practical worksheet, or a sharper decision rule.",
        "4",
        "2",
        true
      ),
      makeCard(
        "evidence",
        "List every claim that needs proof",
        "Mark claims that need screenshots, numbers, examples, client/customer context, source links, or firsthand testing before publishing.",
        "5",
        "3",
        true
      ),
      makeCard(
        "evidence",
        "Add one proof block near the top",
        "Before the article becomes advice-heavy, add a short proof block that shows why your method is credible for " + topic + ".",
        "4",
        "3",
        true
      ),
      makeCard(
        "evidence",
        "Separate opinion from verified fact",
        "Soften or label anything that cannot be supported. Keep the article useful without overclaiming.",
        "4",
        "2",
        true
      ),
      makeCard(
        "faq",
        "Answer the beginner question the competitor skips",
        "Find the question a nervous or new reader would ask before acting on this advice. Put it in the FAQ or early body section.",
        "4",
        "2",
        true
      ),
      makeCard(
        "faq",
        "Add comparison and edge-case FAQs",
        "Create questions around alternatives, failure cases, cost, timing, difficulty, tools, and who should not use the advice.",
        "3",
        "2",
        true
      ),
      makeCard(
        "faq",
        "Turn objections into FAQ entries",
        "Use the FAQ section to handle doubts that could stop the reader from trusting the article.",
        "3",
        "2",
        true
      ),
      makeCard(
        "originality",
        "Name your own framework",
        "Turn your article idea into a simple named method, checklist, scorecard, or sprint. This gives the article a reason to exist beyond rewriting the competitor.",
        "5",
        "3",
        true
      ),
      makeCard(
        "originality",
        "Add lived or operational detail",
        "Add specific examples, mistakes, constraints, screenshots, or decisions that a generic article would not include.",
        "4",
        "3",
        true
      ),
      makeCard(
        "originality",
        "State the article's sharper point of view",
        "Write the one sentence that your article believes more strongly than the competitor does. Keep it defensible.",
        "4",
        "2",
        true
      ),
      makeCard(
        "priority",
        "Choose the top three gaps only",
        "Move only the highest-leverage cards here. These are the changes that should shape the title, intro, outline, and proof plan.",
        "5",
        "1",
        true
      ),
      makeCard(
        "priority",
        "Decide what to cut",
        "Park weak, duplicate, or proof-heavy ideas that would bloat the article without improving the search result.",
        "4",
        "1",
        true
      )
    ];
  }

  function seedBoard() {
    var existing = state.cards.length;
    var fresh = starterCards();

    if (existing > 0) {
      fresh.forEach(function (card) {
        card.included = false;
        card.lane = "parked";
      });
    }

    state.cards = state.cards.concat(fresh);
    save();
    render();
    showToast(existing > 0 ? "Starter gaps added to Parked" : "Starter gaps generated");
  }

  function addCustomCard() {
    var title = cleanText(el.newTitle.value);
    var detail = cleanText(el.newDetail.value);

    if (!title && !detail) {
      showToast("Add a title or note first");
      return;
    }

    state.cards.push(makeCard(
      el.newLane.value,
      title || "Untitled gap",
      detail || "Add the reason this gap matters.",
      "3",
      "2",
      true
    ));

    el.newTitle.value = "";
    el.newDetail.value = "";
    save();
    render();
    showToast("Gap card added");
  }

  function deleteCard(id) {
    state.cards = state.cards.filter(function (card) {
      return card.id !== id;
    });
    save();
    render();
  }

  function moveCard(id, laneId) {
    var card = state.cards.find(function (item) {
      return item.id === id;
    });
    if (card) {
      card.lane = laneId;
      save();
      render();
    }
  }

  function nudgeCard(id, direction) {
    var index = state.cards.findIndex(function (card) {
      return card.id === id;
    });
    if (index < 0) {
      return;
    }

    var card = state.cards[index];
    var sameLane = state.cards
      .map(function (item, itemIndex) {
        return { item: item, index: itemIndex };
      })
      .filter(function (entry) {
        return entry.item.lane === card.lane;
      });

    var lanePos = sameLane.findIndex(function (entry) {
      return entry.item.id === id;
    });

    var targetLanePos = lanePos + direction;
    if (targetLanePos < 0 || targetLanePos >= sameLane.length) {
      return;
    }

    var swapIndex = sameLane[targetLanePos].index;
    var temp = state.cards[index];
    state.cards[index] = state.cards[swapIndex];
    state.cards[swapIndex] = temp;
    save();
    render();
  }

  function impactValue(card) {
    return Number(card.impact || 0);
  }

  function effortValue(card) {
    return Number(card.effort || 0);
  }

  function priorityScore(card) {
    return Math.max(0, impactValue(card) * 2 - effortValue(card));
  }

  function includedCards() {
    return state.cards.filter(function (card) {
      return card.included && card.lane !== "parked";
    });
  }

  function createStat(label, value) {
    var box = document.createElement("div");
    box.className = "stat";

    var strong = document.createElement("strong");
    strong.textContent = String(value);

    var span = document.createElement("span");
    span.textContent = label;

    box.appendChild(strong);
    box.appendChild(span);
    return box;
  }

  function renderStats() {
    var inc = includedCards();
    var high = inc.filter(function (card) {
      return priorityScore(card) >= 7;
    }).length;
    var proof = inc.filter(function (card) {
      return card.lane === "evidence";
    }).length;
    var faq = inc.filter(function (card) {
      return card.lane === "faq";
    }).length;

    el.stats.replaceChildren(
      createStat("Included gaps", inc.length),
      createStat("High priority", high),
      createStat("Proof gaps", proof),
      createStat("FAQ gaps", faq)
    );
  }

  function createTab(id, name) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "tab";
    if (state.filter === id) {
      btn.classList.add("active");
    }
    btn.textContent = name;
    btn.addEventListener("click", function () {
      state.filter = id;
      save();
      render();
    });
    return btn;
  }

  function renderTabs() {
    var nodes = [createTab("all", "All lanes")];
    lanes.forEach(function (lane) {
      nodes.push(createTab(lane.id, lane.name));
    });
    el.tabs.replaceChildren.apply(el.tabs, nodes);
  }

  function fieldLabel(text, control) {
    var label = document.createElement("label");
    label.textContent = text;
    label.appendChild(control);
    return label;
  }

  function makeSelect(value, options, onChange) {
    var select = document.createElement("select");

    options.forEach(function (option) {
      var opt = document.createElement("option");
      opt.value = option.value;
      opt.textContent = option.label;
      if (option.value === value) {
        opt.selected = true;
      }
      select.appendChild(opt);
    });

    select.addEventListener("change", function () {
      onChange(select.value);
    });

    return select;
  }

  function makeButton(text, className, onClick) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = className || "btn tiny";
    btn.textContent = text;
    btn.addEventListener("click", onClick);
    return btn;
  }

  function renderCard(card) {
    var wrap = document.createElement("article");
    wrap.className = "card";
    wrap.draggable = true;
    wrap.dataset.id = card.id;

    wrap.addEventListener("dragstart", function (event) {
      wrap.classList.add("dragging");
      event.dataTransfer.setData("text/plain", card.id);
    });

    wrap.addEventListener("dragend", function () {
      wrap.classList.remove("dragging");
    });

    var top = document.createElement("div");
    top.className = "card-top";

    var title = document.createElement("h3");
    title.className = "card-title";
    title.textContent = card.title || "Untitled gap";

    var pill = document.createElement("span");
    pill.className = "pill";
    pill.textContent = "Score " + priorityScore(card);

    top.appendChild(title);
    top.appendChild(pill);

    var detail = document.createElement("p");
    detail.className = "card-detail";
    detail.textContent = card.detail || "No detail added yet.";

    var grid = document.createElement("div");
    grid.className = "mini-grid";

    var laneSelect = makeSelect(card.lane, lanes.map(function (lane) {
      return { value: lane.id, label: lane.name };
    }), function (value) {
      card.lane = value;
      save();
      render();
    });

    var impactSelect = makeSelect(card.impact || "3", [
      { value: "1", label: "Impact 1" },
      { value: "2", label: "Impact 2" },
      { value: "3", label: "Impact 3" },
      { value: "4", label: "Impact 4" },
      { value: "5", label: "Impact 5" }
    ], function (value) {
      card.impact = value;
      save();
      render();
    });

    var effortSelect = makeSelect(card.effort || "2", [
      { value: "1", label: "Effort 1" },
      { value: "2", label: "Effort 2" },
      { value: "3", label: "Effort 3" },
      { value: "4", label: "Effort 4" },
      { value: "5", label: "Effort 5" }
    ], function (value) {
      card.effort = value;
      save();
      render();
    });

    var titleInput = document.createElement("input");
    titleInput.value = card.title || "";
    titleInput.placeholder = "Card title";
    titleInput.addEventListener("input", function () {
      card.title = titleInput.value;
      save();
      renderBriefOnly();
    });

    grid.appendChild(fieldLabel("Lane", laneSelect));
    grid.appendChild(fieldLabel("Title", titleInput));
    grid.appendChild(fieldLabel("Impact", impactSelect));
    grid.appendChild(fieldLabel("Effort", effortSelect));

    var note = document.createElement("textarea");
    note.className = "note";
    note.value = card.note || "";
    note.placeholder = "Brief note, rewrite angle, proof needed, or FAQ wording.";
    note.addEventListener("input", function () {
      card.note = note.value;
      save();
      renderBriefOnly();
    });

    var includeRow = document.createElement("label");
    includeRow.className = "include-row";

    var include = document.createElement("input");
    include.type = "checkbox";
    include.checked = card.included !== false;
    include.addEventListener("change", function () {
      card.included = include.checked;
      save();
      render();
    });

    var includeText = document.createElement("span");
    includeText.textContent = "Include in copied brief";

    includeRow.appendChild(include);
    includeRow.appendChild(includeText);

    var actions = document.createElement("div");
    actions.className = "card-actions";
    actions.appendChild(makeButton("↑", "btn tiny", function () {
      nudgeCard(card.id, -1);
    }));
    actions.appendChild(makeButton("↓", "btn tiny", function () {
      nudgeCard(card.id, 1);
    }));
    actions.appendChild(makeButton("Priority", "btn tiny", function () {
      moveCard(card.id, "priority");
    }));
    actions.appendChild(makeButton("Park", "btn tiny", function () {
      moveCard(card.id, "parked");
    }));
    actions.appendChild(makeButton("Delete", "btn tiny warn", function () {
      deleteCard(card.id);
    }));

    wrap.appendChild(top);
    wrap.appendChild(detail);
    wrap.appendChild(grid);
    wrap.appendChild(note);
    wrap.appendChild(includeRow);
    wrap.appendChild(actions);

    return wrap;
  }

  function renderLane(lane) {
    var laneBox = document.createElement("section");
    laneBox.className = "lane";
    laneBox.dataset.lane = lane.id;

    laneBox.addEventListener("dragover", function (event) {
      event.preventDefault();
      laneBox.classList.add("drop");
    });

    laneBox.addEventListener("dragleave", function () {
      laneBox.classList.remove("drop");
    });

    laneBox.addEventListener("drop", function (event) {
      event.preventDefault();
      laneBox.classList.remove("drop");
      var id = event.dataTransfer.getData("text/plain");
      if (id) {
        moveCard(id, lane.id);
      }
    });

    var laneCards = state.cards.filter(function (card) {
      return card.lane === lane.id;
    });

    var head = document.createElement("div");
    head.className = "lane-head";

    var text = document.createElement("div");
    var name = document.createElement("h3");
    name.className = "lane-name";
    name.textContent = lane.name;

    var desc = document.createElement("p");
    desc.className = "lane-desc";
    desc.textContent = lane.desc;

    text.appendChild(name);
    text.appendChild(desc);

    var count = document.createElement("span");
    count.className = "count";
    count.textContent = String(laneCards.length);

    head.appendChild(text);
    head.appendChild(count);

    var cards = document.createElement("div");
    cards.className = "cards";

    if (laneCards.length === 0) {
      var empty = document.createElement("div");
      empty.className = "empty";
      empty.textContent = "No cards here yet.";
      cards.appendChild(empty);
    } else {
      laneCards.forEach(function (card) {
        cards.appendChild(renderCard(card));
      });
    }

    laneBox.appendChild(head);
    laneBox.appendChild(cards);
    return laneBox;
  }

  function renderBoard() {
    var visible = lanes.filter(function (lane) {
      return state.filter === "all" || state.filter === lane.id;
    });

    el.board.replaceChildren.apply(el.board, visible.map(renderLane));
  }

  function groupCards() {
    var groups = {};
    lanes.forEach(function (lane) {
      groups[lane.id] = [];
    });

    includedCards()
      .slice()
      .sort(function (a, b) {
        return priorityScore(b) - priorityScore(a);
      })
      .forEach(function (card) {
        groups[card.lane].push(card);
      });

    return groups;
  }

  function cardLine(card) {
    var parts = [];
    parts.push("- " + (card.title || "Untitled gap") + " | score " + priorityScore(card));
    if (cleanText(card.note)) {
      parts.push("  Note: " + cleanText(card.note));
    } else if (cleanText(card.detail)) {
      parts.push("  Note: " + cleanText(card.detail));
    }
    return parts.join("\n");
  }

  function buildBrief() {
    var groups = groupCards();
    var topic = cleanText(el.topic.value) || "Not set";
    var audience = cleanText(el.audience.value) || "Not set";
    var competitor = cleanText(el.competitor.value) || "Not set";
    var idea = cleanText(el.idea.value) || "Not set";

    var allIncluded = includedCards().slice().sort(function (a, b) {
      return priorityScore(b) - priorityScore(a);
    });

    var topFive = allIncluded.slice(0, 5);
    var proofNeeds = groups.evidence || [];
    var faqNeeds = groups.faq || [];

    var lines = [];
    lines.push("CONTENT GAP BRIEF");
    lines.push("");
    lines.push("Topic or keyword");
    lines.push(topic);
    lines.push("");
    lines.push("Audience");
    lines.push(audience);
    lines.push("");
    lines.push("Competitor article or angle");
    lines.push(competitor);
    lines.push("");
    lines.push("My article idea");
    lines.push(idea);
    lines.push("");
    lines.push("Recommended positioning");
    lines.push("Write the article around the strongest specific promise, then support it with proof, missing FAQs, and a fresher framework than the competitor.");
    lines.push("");

    lines.push("Top next actions");
    if (topFive.length) {
      topFive.forEach(function (card, index) {
        lines.push(String(index + 1) + ". " + (card.title || "Untitled gap") + " | " + getLaneName(card.lane) + " | score " + priorityScore(card));
      });
    } else {
      lines.push("- Add or include at least one gap card.");
    }
    lines.push("");

    lanes.forEach(function (lane) {
      if (lane.id === "parked") {
        return;
      }

      lines.push(lane.name.toUpperCase());
      if (groups[lane.id] && groups[lane.id].length) {
        groups[lane.id].forEach(function (card) {
          lines.push(cardLine(card));
        });
      } else {
        lines.push("- No included cards.");
      }
      lines.push("");
    });

    lines.push("Claims to prove before publishing");
    if (proofNeeds.length) {
      proofNeeds.slice(0, 8).forEach(function (card) {
        lines.push("- " + (card.title || "Evidence gap") + ": " + (cleanText(card.note) || cleanText(card.detail) || "Add support."));
      });
    } else {
      lines.push("- No proof gaps listed yet.");
    }
    lines.push("");

    lines.push("FAQ candidates");
    if (faqNeeds.length) {
      faqNeeds.slice(0, 8).forEach(function (card) {
        lines.push("- " + (cleanText(card.note) || card.title || "FAQ to add"));
      });
    } else {
      lines.push("- No FAQ gaps listed yet.");
    }
    lines.push("");

    var parked = state.cards.filter(function (card) {
      return card.lane === "parked";
    });

    lines.push("Parked or skipped");
    if (parked.length) {
      parked.slice(0, 10).forEach(function (card) {
        lines.push("- " + (card.title || "Untitled parked card"));
      });
    } else {
      lines.push("- Nothing parked.");
    }

    return lines.join("\n");
  }

  function renderBriefOnly() {
    el.briefPreview.textContent = buildBrief();
  }

  function render() {
    renderTabs();
    renderStats();
    renderBoard();
    renderBriefOnly();
  }

  function copyBrief() {
    var text = buildBrief();

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () {
        showToast("Brief copied");
      }).catch(function () {
        fallbackCopy(text);
      });
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text) {
    var area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.left = "-9999px";
    document.body.appendChild(area);
    area.select();

    try {
      document.execCommand("copy");
      showToast("Brief copied");
    } catch (err) {
      showToast("Copy failed. Select the preview text.");
    }

    document.body.removeChild(area);
  }

  function exportBrief() {
    var text = buildBrief();
    var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    var name = cleanText(el.topic.value).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "content-gap-brief";
    a.href = url;
    a.download = name + ".txt";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Brief exported");
  }

  function resetBoard() {
    var ok = window.confirm("Reset this board and clear saved cards?");
    if (!ok) {
      return;
    }

    state = {
      topic: "",
      audience: "",
      competitor: "",
      idea: "",
      filter: "all",
      cards: []
    };

    el.topic.value = "";
    el.audience.value = "";
    el.competitor.value = "";
    el.idea.value = "";
    el.newTitle.value = "";
    el.newDetail.value = "";

    save();
    render();
    showToast("Board reset");
  }

  var saveAndRenderBrief = debounce(function () {
    save();
    renderBriefOnly();
    renderStats();
  }, 150);

  [el.topic, el.audience, el.competitor, el.idea].forEach(function (input) {
    input.addEventListener("input", saveAndRenderBrief);
  });

  el.seedBtn.addEventListener("click", seedBoard);
  el.addBtn.addEventListener("click", addCustomCard);
  el.copyBtn.addEventListener("click", copyBrief);
  el.exportBtn.addEventListener("click", exportBrief);
  el.resetBtn.addEventListener("click", resetBoard);

  load();

  if (!state.cards.length) {
    state.cards = [
      makeCard("promise", "Clarify the result promise", "Make the title and intro promise a specific outcome instead of a generic overview.", "5", "2", true),
      makeCard("evidence", "Identify proof gaps", "List claims that need examples, screenshots, data, firsthand testing, or source links.", "5", "3", true),
      makeCard("faq", "Add missing reader questions", "Capture the questions a cautious reader would ask before acting.", "4", "2", true),
      makeCard("originality", "Add a unique framework", "Give your article a named method, scorecard, checklist, or angle the competitor does not have.", "5", "3", true),
      makeCard("priority", "Pick the top three improvements", "Move only the highest-leverage gaps here before writing the brief.", "5", "1", true)
    ];
    save();
  }

  render();
})();
</script>
</body>
</html>

